const crypto = require('crypto');
const webhookData = $input.first().json;

// Generate or use provided job_id
const job_id = webhookData.body.job_id || crypto.randomUUID();
const callback_url = webhookData.body.callback_url;

return [{
  json: {
    ...webhookData,
    job_context: {
      job_id: job_id,
      callback_url: callback_url,
      started_at: new Date().toISOString()
    }
  }
}];

const items = $input.all();
const jobContextData = $('Store Job Context').first().json;
const webhookData = jobContextData;

const PRICING = {
  'dall-e-3': {
    'standard': { '1024x1024': 0.04, '1792x1024': 0.08, '1024x1792': 0.08 },
    'hd': { '1024x1024': 0.08, '1792x1024': 0.12, '1024x1792': 0.12 }
  },
  'dall-e-2': {
    'standard': { '256x256': 0.016, '512x512': 0.018, '1024x1024': 0.02 }
  }
};

const results = items.map(item => {
  // Check for API errors
  if (item.json.error) {
    return {
      json: {
        success: false,
        job_id: jobContextData.job_context.job_id,
        status: 'failed',
        error: {
          code: item.json.error.code || 500,
          message: item.json.error.message || 'Unknown error',
          status: item.json.error.type || 'API_ERROR'
        },
        meta: {
          provider: 'openai',
          execution_mode: webhookData.body.execution_mode || 'online'
        },
        job_context: jobContextData.job_context
      }
    };
  }

  const model = webhookData.body.options?.model || 'dall-e-3';
  const quality = webhookData.body.options?.quality || 'standard';
  const size = webhookData.body.options?.size || '1024x1024';
  const n = webhookData.body.options?.n || 1;

  const unitPrice = PRICING[model]?.[quality]?.[size] || 0.04;
  const costEstimate = unitPrice * n;

  const images = (item.json.data || []).map(img => ({
    url: img.url || null,
    b64_json: img.b64_json || null,
    revised_prompt: img.revised_prompt || null,
    size: size
  }));

  return {
    json: {
      success: true,
      job_id: jobContextData.job_context.job_id,
      status: 'completed',
      data: {
        images: images,
        prompt_original: webhookData.body.prompt,
        prompt_revised: images[0]?.revised_prompt || null
      },
      meta: {
        provider: 'openai',
        model: model,
        execution_mode: webhookData.body.execution_mode || 'online',
        cost_estimate_usd: costEstimate
      },
      job_context: jobContextData.job_context
    }
  };
});

return results;

const crypto = require('crypto');
const item = $input.first().json;

// Extract callback URL from job context
const callback_url = item.job_context.callback_url;

// Prepare the callback body (without job_context internal data)
const callbackBody = {
  success: item.success,
  job_id: item.job_id,
  status: item.status,
  data: item.data,
  meta: item.meta
};

if (item.error) {
  callbackBody.error = item.error;
}

// Generate HMAC signature (RFC-040 format)
const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';
const payload = JSON.stringify(callbackBody);
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return [{
  json: {
    callback_url: callback_url,
    callback_body: callbackBody,
    signature: signature
  }
}];

